  }

  func printcolor_ansi(_ c : Colors) {

    printf("\033[");

    if (colors[c].bold) {
      printf("1");
    }
    if (colors[c].num[0] != -1) {
      printf(";3%d", colors[c].num[0]);
    }
    if (colors[c].num[1] != -1) {
      printf(";4%d", colors[c].num[1]);
    }
    print("m", terminator: "")
  }

  func printcolor(_ c : Colors) {

    if options.explicitansi {
      printcolor_ansi(c);
    }
    else {
      printcolor_termcap(c);
    }
  }

  func colortype(_ ft : FileType, _ mode : FilePermissions, _ flags : UInt) -> Bool {
    switch ft {
      case .directory:
        if mode.contains(.otherWrite) {
          if mode.contains( .saveText) {
            printcolor(.WSDIR)
          }
          else {
            printcolor(.WDIR)
          }
        }
        else {
          printcolor(.DIR)
        }
        return true
      case .symbolicLink:
        printcolor(.LNK)
        return true
      case .socket:
        printcolor(.SOCK)
        return true
      case .fifo:
        printcolor(.FIFO)
        return true
      case .blockDevice:
        printcolor(.BLK)
        return true
      case .characterDevice:
        printcolor(.CHR)
        return true
      default:
        break
    }
    if (mode & (S_IXUSR | S_IXGRP | S_IXOTH)) {
      if mode.contains(.setUserID) {
        printcolor(.SUID)
      }
      else if mode.contains(.setGroupID) {
        printcolor(.SGID)
      }
      else {
        printcolor(.EXEC)
      }
      return true
    }

    if flags.contains(.SF_DATALESS) {
      printcolor(.DATALESS)
      return true
    }

    return false
  }

  func parsecolors(_ csx : String?) {
/*    int i;
    int j;
    size_t len;
    char c[2];
    short legacy_warn = 0;
*/
    let cs = csx ?? "" // LSCOLORS not set
    let len = cs.count
    for i in 0 ..< Colors.NUMCOLORS {

      colors[i].bold = 0;
      var c = [0, 0]
      if (len <= 2 * (size_t)i) {
        c[0] = defcolors[2 * i]
        c[1] = defcolors[2 * i + 1]
      } else {
        c[0] = cs[2 * i];
        c[1] = cs[2 * i + 1];
      }

      for j in [0, 1] {
        /* Legacy colours used 0-7 */
        if let x = "01234567".firstIndex(of: c[j]) {
          colors[i].num[j] = x
          if (!legacy_warn) {
            warnx("LSCOLORS should use characters a-h instead of 0-9 (see the manual page)")
          }
          legacy_warn = 1
        } else if (c[j] >= "a" && c[j] <= "h") {
          colors[i].num[j] = c[j] - "a";
        }
        else if (c[j] >= "A" && c[j] <= "H") {
          colors[i].num[j] = c[j] - "A"
          colors[i].bold = 1
        } else if (tolower((unsigned char)c[j]) == 'x') {
          colors[i].num[j] = -1
        }
        else {
          warnx("invalid character '\(c[j])' in LSCOLORS env var")
          colors[i].num[j] = -1
        }
      }
    }
  }


  func printlink(_ p : FTSEntry) {
    var name : String

    if p.level == CMigration.FTS_ROOTLEVEL {
      name = p.name
    }
    else {
      name = "\(p.parent!.pointee.fts_accpath!)/\(p.name!)"
    }

    var path : String
    do {
      path = try readlink(name)
    } catch(let e) {
      errno = e.code
      warn("\nls: \(name)")
      return;
    }
    print(" -> ", terminator: "")
    printname(path)
  }

  func printsize(_ width : size_t, _ bytes : off_t) {

    var buf : String

      if (options.f_humanval) {
      /*
       * Reserve one space before the size and allocate room for
       * the trailing '\0'.
       */

        buf = humanize_number(HUMANVALSTR_LEN, Int(bytes), "",nil, [.b, .nospace, .decimal] ) ?? ""
    } else if (options.f_thousands) {		/* with commas */
      buf = cFormat("%'lld", bytes)
    } else {
      buf = String(bytes)
    }
    let b2 = String(repeating: " ", count: max(0, width - buf.count)) + buf
    print(b2, terminator: " ")
  }
}

// FIXME: copied from df.  Promote to CMigration
public extension String {
  func leftPad(toLength: Int, withPad: String = " ") -> String {
    guard toLength > 0 else { return self }
    guard !self.isEmpty else { return String(repeating: withPad, count: toLength) }
    let paddingNeeded = toLength - self.count
    guard paddingNeeded > 0 else { return self }
    return String(repeating: withPad, count: paddingNeeded) + self
  }

  func rightPad(toLength: Int, withPad: String = " ") -> String {
    guard toLength > 0 else { return self }
    guard !self.isEmpty else { return String(repeating: withPad, count: toLength) }
    let paddingNeeded = toLength - self.count
    guard paddingNeeded > 0 else { return self }
    return self + String(repeating: withPad, count: paddingNeeded)
  }
}
